"""Standalone desktop concept; reads aggregates without changing application data."""
from pathlib import Path
import sqlite3, json, html, shutil
root = Path(__file__).resolve().parents[3]
out = root / 'docs/design-review/retailos-taste'
out.mkdir(parents=True, exist_ok=True)
db=sqlite3.connect((root/'data/retailos.db').as_uri()+'?mode=ro',uri=True)
day=db.execute('select max(business_date) from sales_day').fetchone()[0]
series=db.execute('select business_date,sum(net_sales),sum(tx_count) from sales_day where business_date>=date(?,\'-6 days\') group by business_date order by business_date',(day,)).fetchall()
stores=db.execute('select l.name,l.source,sum(s.net_sales),sum(s.tx_count),coalesce((select sum(y.net_sales) from sales_day y where y.location_id=l.id and y.business_date=date(?,\'-1 day\')),0) from sales_day s join location l on l.id=s.location_id where business_date=? group by l.id order by 3 desc',(day,day)).fetchall()
mix=db.execute('select l.source,sum(s.net_sales) from sales_day s join location l on l.id=s.location_id where business_date=? group by l.source',(day,)).fetchall()
def count(table,where): return db.execute('select count(*) from '+table+' where '+where).fetchone()[0]
pending=count('recommendation',"status='pending'"); issues=count('issue',"status='open'"); pos=count('purchase_order',"status in ('open','partiallyReceived')"); transfers=count('transfer_sheet',"status='draft'")
db.close()
sprite=(root/'app/web/templates/_icons.html').read_text(encoding='utf-8')
shutil.copyfile(root/'app/web/static/retailos-mark.svg',out/'retailos-mark.svg')
motion=out/'assets/motion'
motion.mkdir(parents=True,exist_ok=True)
for f in ('motion.css','motion.js'):
    shutil.copyfile(Path(__file__).parent/'assets/motion'/f,motion/f)
def icon(name):return '<svg class="icon" aria-hidden="true"><use href="#i-'+name+'"/></svg>'
def nav(label,ic,active=False,count=None):return f'<a class="navitem {"active" if active else ""}">{icon(ic)}<span>{label}</span>{"<em>"+str(count)+"</em>" if count else ""}</a>'
navhtml=nav('Overview','home',True)+'<div class="nav-label">STORE OPERATIONS</div>'+nav('Problems','alert',count=issues)+nav('Inspections','clipboard')+nav('Stock counts','count')+nav('Stock changes','camera')+'<div class="nav-label">INVENTORY & ORDERS</div>'+nav('Inventory','box')+nav('Auto replenishment','trend',count=pending)+nav('Purchasing','file')+nav('Transfers','sync')+nav('7-Eleven','file')+'<div class="nav-label">BUSINESS INSIGHTS</div>'+nav('Sales & reports','chart')+nav('Employees','user')
money=lambda n:f'{n:,.2f}'
sales=series[-1][1]; tx=series[-1][2]; trading=sum(r[2]>0 for r in stores)
points=[(i*100/(len(series)-1), 115-(r[1]/max(t[1] for t in series))*95) for i,r in enumerate(series)]
line=' '.join(('M' if i==0 else 'L')+f'{x*7.6+12:.1f},{y:.1f}' for i,(x,y) in enumerate(points))
area=line+' L772,132 L12,132 Z'
chart=''.join(f'<path d="M0 {y}H788" stroke="#e7ebf0" stroke-dasharray="3 5"/>' for y in [20,58,96,132])+f'<path d="{area}" fill="url(#fill)"/><path d="{line}" fill="none" stroke="#3568e8" stroke-width="2.7"/>'+''.join(f'<circle cx="{x*7.6+12:.1f}" cy="{y:.1f}" r="3.5" fill="white" stroke="#3568e8" stroke-width="2"/>' for x,y in points)
storehtml=''
for i,(name,source,amount,n,yesterday) in enumerate(stores[:7]):
    clean=name.replace('The Daily Centro - ','').replace('TheDailyCentro','Daily Centro')
    source_label='StoreHub' if source=='storehub' else 'Loyverse'
    storehtml+=f'<tr><td><span class="store-icon">{icon("box")}</span><span><b>{html.escape(clean)}</b><small>{source_label}</small></span></td><td>{money(amount)}</td><td>{n:,}</td><td>{money(yesterday)}</td><td><div class="share"><i style="width:{amount/sales*100:.2f}%"></i></div><small>{amount/sales*100:.1f}%</small></td><td>{icon("arrow")}</td></tr>'
qhtml=''
for name,countval,note,ic in [('Replenishment',pending,'Suggestions awaiting review','trend'),('Purchase orders',pos,'Open or partially received','file'),('Store issues',issues,'Open issues across your stores','alert'),('Transfer sheets',transfers,'Draft sheets to complete','sync')]:
    qhtml+=f'<div class="queue-row"><span class="queue-icon">{icon(ic)}</span><div><b>{name}</b><small>{note}</small></div><strong>{countval:,}</strong>{icon("arrow")}</div>'
colors=['#3568e8','#8aabf7']; offset=0;segments=''; mixhtml=''
for i,(source,amount) in enumerate(mix):
    frac=amount/sales*100;segments+=f'<circle cx="65" cy="65" r="51" fill="none" stroke="{colors[i%2]}" stroke-width="12" stroke-dasharray="{frac*3.2044} 320.44" stroke-dashoffset="{-offset*3.2044}" transform="rotate(-90 65 65)"/>';offset+=frac
    mixhtml+=f'<div class="mix-row"><span><i style="background:{colors[i%2]}"></i>{"StoreHub" if source=="storehub" else "Loyverse"}</span><b>{frac:.1f}%</b><small>₱{money(amount)}</small></div>'
page='''<!doctype html><html lang="en" data-type="software" data-radius="soft" data-motion><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="page-type" content="software"><meta name="site-kind" content="software"><title>Retail OS · Desktop workspace concept</title><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="../seven-taste/assets/motion/motion.css"><style>
:root{--ink:#182236;--muted:#778093;--line:#e8ecf2;--action:#3568e8;--r-btn:8px}*{box-sizing:border-box}body{margin:0;font:13px/1.5 Manrope,system-ui,sans-serif;background:#f3f5f9;color:var(--ink);font-variant-numeric:tabular-nums}button,input{font:inherit}.icon{height:18px;width:18px;fill:none;stroke:currentColor;stroke-width:1.65;flex:none}.app{display:grid;grid-template-columns:238px minmax(0,1fr);min-height:100vh}.rail{background:#152031;color:#afb8c9;padding:28px 16px 20px;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:12px;padding:0 12px 30px;color:white;font-size:21px;font-weight:800;letter-spacing:-.7px}.brand img{width:37px;height:37px}.brand small{font-size:10px;display:block;font-weight:400;color:#8e9aae;letter-spacing:.6px;margin-top:1px}.nav-label{font-size:9px;letter-spacing:1.2px;font-weight:700;color:#65758d;margin:24px 12px 9px}.navitem{display:flex;gap:12px;align-items:center;padding:10px 12px;border-radius:8px;cursor:pointer;margin:2px 0;font-size:12px;font-weight:600}.navitem span{flex:1}.navitem .icon{width:17px;height:17px}.navitem em{font-size:10px;line-height:20px;font-style:normal;background:#29364b;color:#bbcae1;padding:0 7px;border-radius:5px}.navitem.active{color:#fff;background:#2f64df;box-shadow:0 6px 16px #09152b55}.navitem:hover:not(.active){background:#1f2d42;color:white}.rail-bottom{margin-top:auto;padding-top:24px}.assistant-tile{border:1px solid #35445b;background:#1d2a3d;padding:14px;border-radius:10px;color:#fff;display:flex;gap:10px;align-items:center;font-size:12px;font-weight:600}.assistant-tile small{display:block;font-size:10px;color:#8fa0b8;font-weight:400;margin-top:3px}.assistant-tile img{width:27px}.profile{border-top:1px solid #2a374c;display:flex;gap:10px;align-items:center;margin-top:20px;padding:20px 10px 0}.avatar{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#dce7ff;color:#2951a8;font-size:12px;font-weight:700}.profile small{display:block;color:#7e8da3;font-size:10px}.workspace{min-width:0}.top{height:72px;padding:0 32px;background:white;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:20px}.crumb{font-size:12px;color:var(--muted)}.crumb b{font-weight:600;color:#38445a;margin-left:10px}.search{margin-left:auto;display:flex;align-items:center;gap:9px;border:1px solid var(--line);border-radius:7px;padding:8px 12px;color:#929bad;width:280px;background:#fafbfd}.search input{border:0;background:none;min-width:0;width:100%;font-size:11px;outline:none}.search kbd{font:10px Manrope;white-space:nowrap;border:1px solid #dfe5ee;border-radius:4px;padding:0 4px}.top button{background:none;border:0;color:#637087;cursor:pointer}.top-divider{height:25px;width:1px;background:var(--line)}.work{padding:24px 32px 28px}.businesses{display:flex;gap:6px;align-items:center;padding:4px;background:#e9edf4;border-radius:8px;width:max-content}.businesses button{border:0;background:none;color:#7b8598;border-radius:6px;padding:7px 14px;font-weight:600;font-size:11px;cursor:pointer}.businesses .on{background:white;color:#263755;box-shadow:0 2px 5px #2c426015}.scope-row{display:flex;align-items:center;justify-content:space-between}.scope-row>span{font-size:10px;color:#8390a2}.scope-row i{display:inline-block;width:5px;height:5px;border-radius:50%;background:#98a4b4;margin:0 6px 1px}.heading{display:flex;align-items:center;justify-content:space-between;margin:24px 0 22px}h1{font-size:26px;letter-spacing:-.8px;font-weight:800;line-height:1.2;margin:0}.heading p{margin:6px 0 0;font-size:11px;color:var(--muted)}.actions{display:flex;gap:8px}.btn{height:36px;padding:0 13px;border-radius:7px;background:#fff;border:1px solid #dde3ec;display:inline-flex;align-items:center;gap:8px;font-size:11px;color:#4b596f;font-weight:600;cursor:pointer}.btn.primary{color:white;background:#3568e8;border-color:#3568e8}.btn .icon{width:14px;height:14px}.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--line);border-radius:11px;background:white;padding:20px 0;margin-bottom:20px}.kpi{padding:0 24px;border-right:1px solid var(--line);position:relative}.kpi:last-child{border:0}.metric-label{color:#6c7990;font-size:11px;display:flex;align-items:center;gap:8px}.metric-label .icon{width:15px;color:#8293b2}.metric-val{font-size:27px;font-weight:800;letter-spacing:-1px;margin:8px 0 3px}.metric-val em{font-style:normal;font-size:17px;color:#99a4b6;font-weight:500;letter-spacing:0}.kpi small{font-size:10px;color:#94a0b2}.kpi .blue{color:#3568e8}.kpi .amber{color:#b57b29}.canvas{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:20px}.panel{border:1px solid var(--line);border-radius:11px;background:white;min-width:0;overflow:hidden}.panel-head{padding:19px 20px;display:flex;align-items:center;justify-content:space-between}.panel-head h2{margin:0;font-size:13px;font-weight:800;letter-spacing:-.2px}.panel-head p{font-size:10px;color:#8b97aa;margin:3px 0 0}.panel-head a{font-size:10px;color:#3568e8;text-decoration:none;font-weight:700}.plot{padding:0 20px 12px}.plot-meta{display:flex;align-items:center;gap:16px;margin-bottom:14px;font-size:10px;color:#8c98aa}.plot-meta span:first-child{color:#4e5e78;font-weight:600}.dot{height:6px;width:6px;display:inline-block;border-radius:50%;background:#3568e8;margin-right:6px}.plot-body{display:grid;grid-template-columns:45px minmax(0,1fr);gap:10px}.axis{display:flex;flex-direction:column;justify-content:space-between;padding-bottom:4px;font-size:9px;color:#99a4b5}.plot svg{width:100%;height:156px;display:block;overflow:visible}.xaxis{display:flex;justify-content:space-between;margin-left:55px;padding:12px 0 4px;color:#98a2b1;font-size:9px}.sales-caption{margin:12px 0 0;padding:12px 0 0;border-top:1px solid var(--line);font-size:10px;color:#8290a4;display:flex;justify-content:space-between}.sales-caption strong{color:#4e5d75;font-weight:700}.queue-row{display:flex;align-items:center;gap:10px;padding:13px 0;border-bottom:1px solid #eef1f5}.queue-row:last-child{border:0}.queue{padding:0 20px 4px}.queue-icon{height:32px;width:32px;border-radius:8px;background:#f0f4fc;color:#5a7dc1;display:grid;place-items:center}.queue-icon .icon{height:16px;width:16px}.queue-row>div{flex:1}.queue-row b{font-size:11px;font-weight:700}.queue-row small{display:block;font-size:9px;color:#96a0b1;margin-top:2px}.queue-row strong{font-size:17px;font-weight:800}.queue-row>.icon{width:12px;color:#a4afc0}.queue-note{font-size:9px;background:#f7f9fc;color:#8290a5;padding:10px 20px}.lower{margin-top:20px}.store-table{width:100%;border-collapse:collapse;font-size:11px}.store-table th{font-size:9px;font-weight:600;color:#96a0b1;background:#fbfcfe;text-align:right;padding:10px 16px;border-block:1px solid #edf1f6}.store-table th:first-child{text-align:left}.store-table td{padding:10px 16px;text-align:right;border-bottom:1px solid #f0f3f7;font-weight:600}.store-table tr:last-child td{border:0}.store-table td:first-child{text-align:left;display:flex;gap:10px;align-items:center;white-space:nowrap}.store-table td:first-child b{font-size:10px}.store-table small{font-size:9px;display:block;font-weight:400;color:#97a2b5}.store-icon{width:28px;height:28px;border-radius:7px;display:grid;place-items:center;background:#f1f5fb;color:#6684b9}.store-icon .icon{width:14px;height:14px}.store-table td:last-child{color:#aab5c4}.store-table td:last-child .icon{width:12px}.share{display:inline-block;width:50px;height:4px;background:#eff2f7;border-radius:8px;vertical-align:middle;margin-right:7px}.share i{display:block;height:100%;background:#7e9ef0;border-radius:8px}.store-table td:nth-child(5) small{display:inline-block}.mix{padding:0 20px 16px}.donut{display:flex;gap:18px;align-items:center;margin-bottom:12px}.donut svg{width:128px;height:128px;flex:none}.donut strong{font-size:20px;display:block;letter-spacing:-.5px}.donut small{font-size:9px;color:#9ba5b6}.mix-row{display:grid;grid-template-columns:1fr auto;gap:3px;margin:14px 0;font-size:10px}.mix-row span{color:#697890}.mix-row i{display:inline-block;width:6px;height:6px;border-radius:3px;margin-right:7px}.mix-row small{grid-column:1/-1;margin-left:13px;color:#98a3b6;font-size:9px}.quick{margin-top:20px}.quick .panel-head{padding-bottom:10px}.quick-grid{padding:0 20px 10px}.quick-grid a{display:flex;align-items:center;gap:10px;padding:9px 0;color:#5f708a;font-size:11px;text-decoration:none;border-bottom:1px solid #f1f4f8}.quick-grid a:last-child{border:0}.quick-grid a .icon:last-child{width:12px;margin-left:auto;color:#abb5c3}.footer{margin-top:20px;font-size:9px;color:#9aa5b6;display:flex;justify-content:space-between}a{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid #3568e8;outline-offset:3px}@media(max-width:1400px){.canvas{grid-template-columns:minmax(0,1fr) 285px}.work{padding:24px}.kpi{padding:0 18px}.metric-val{font-size:24px}.store-table th,.store-table td{padding-inline:12px}}
</style></head><body>SPRITE<!-- Internal software workspace concept. Taste principles: restrained neutral surfaces, one accent, aligned edges, real report data, clear type hierarchy. -->
<div class="app"><aside class="rail"><div class="brand"><img src="retailos-mark.svg" alt=""> <span>Retail OS<small>RETAIL WORKSPACE</small></span></div>NAV<div class="rail-bottom"><div class="assistant-tile"><img src="retailos-mark.svg" alt=""><span>Ask Retail OS<small>Get answers from your data</small></span></div><div class="profile"><span class="avatar">A</span><span style="flex:1;color:#eef2f9;font-size:12px">Admin<small>English · 中文</small></span>SETTINGS</div></div></aside><div class="workspace"><header class="top"><span class="crumb">Workspace <b>/ Overview</b></span><label class="search">SEARCH<input id="find" placeholder="Find a store, product or report"><kbd>Ctrl K</kbd></label><button>Print report</button><span class="top-divider"></span>BELL<span class="avatar">A</span></header><main class="work"><div class="scope-row"><div class="businesses"><button class="on">All businesses</button><button>Daily Centro</button><button>Steamy Co.</button><button>Publico</button><button>SipStop</button><button>7-Eleven</button></div><span>Connected sources<i></i>StoreHub + Loyverse</span></div><div class="heading"><div><h1>Business overview</h1><p>Your sales, stores and operational work in one workspace.</p></div><div class="actions"><button class="btn">CALENDAR 7 Nov 2026</button><button class="btn primary">PLUS New stock count</button></div></div><section class="kpis"><div class="kpi"><div class="metric-label">CHART Net sales</div><div class="metric-val"><em>₱</em> SALES</div><small>Latest imported day · 7 Nov</small></div><div class="kpi"><div class="metric-label">LIST Transactions</div><div class="metric-val">TX</div><small>Average basket · ₱AVG</small></div><div class="kpi"><div class="metric-label">BOX Stores with sales</div><div class="metric-val blue">TRADING</div><small>Across connected POS accounts</small></div><div class="kpi"><div class="metric-label">ALERT Open issues</div><div class="metric-val amber">ISSUES</div><small>Review in store operations</small></div></section><div class="canvas"><section class="panel"><div class="panel-head"><div><h2>Sales performance</h2><p>Net sales across connected stores</p></div><button class="btn">Last 7 days⌄</button></div><div class="plot"><div class="plot-meta"><span><i class="dot"></i>Net sales · PHP</span><span>1–7 November 2026</span></div><div class="plot-body"><div class="axis"><span>120k</span><span>80k</span><span>40k</span><span>0</span></div><svg viewBox="0 0 788 140" preserveAspectRatio="none"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#3568e8" stop-opacity=".16"/><stop offset="100%" stop-color="#3568e8" stop-opacity=".01"/></linearGradient></defs>CHARTDATA</svg></div><div class="xaxis"><span>01 Nov</span><span>02 Nov</span><span>03 Nov</span><span>04 Nov</span><span>05 Nov</span><span>06 Nov</span><span>07 Nov</span></div><div class="sales-caption"><span>Latest day may be incomplete until trading closes.</span><span>7-day total <strong>₱WEEK</strong></span></div></div></section><section class="panel"><div class="panel-head"><div><h2>Your work queue</h2><p>Records waiting for review</p></div><a>View all ↗</a></div><div class="queue">QUEUE</div><div class="queue-note">Local operational records · current status</div></section></div><div class="canvas lower"><section class="panel"><div class="panel-head"><div><h2>Store performance</h2><p>Ranked by net sales · 7 November</p></div><a>All stores ↗</a></div><table class="store-table"><thead><tr><th>Store / POS source</th><th>Net sales (PHP)</th><th>Transactions</th><th>Yesterday (PHP)</th><th>Sales share</th><th></th></tr></thead><tbody>STORES</tbody></table></section><div><section class="panel"><div class="panel-head"><div><h2>Sales by source</h2><p>Latest imported day</p></div></div><div class="mix"><div class="donut"><svg viewBox="0 0 130 130">SEGMENTS<text x="65" y="62" text-anchor="middle" fill="#263650" font-size="18" font-weight="700">2</text><text x="65" y="80" text-anchor="middle" fill="#8a98ad" font-size="10">POS sources</text></svg><div><strong>100%</strong><small>of recorded net sales</small></div></div>MIX</div></section><section class="panel quick"><div class="panel-head"><h2>Quick actions</h2></div><div class="quick-grid"><a href="http://localhost:8000/counts">COUNT Start a stock count ARROW</a><a href="http://localhost:8000/transfer-sheets">SYNC Create a transfer sheet ARROW</a><a href="http://localhost:8000/purchase-orders">FILE Review purchase orders ARROW</a></div></section></div></div><footer class="footer"><span>Retail OS · Desktop workspace design concept</span><span>Read-only snapshot · 7 November 2026</span></footer></main></div></div><script>document.getElementById('find').addEventListener('input',function(){document.querySelectorAll('.store-table tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(this.value.toLowerCase()))});document.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key==='k'){e.preventDefault();document.getElementById('find').focus()}});</script><script type="module" src="../seven-taste/assets/motion/motion.js"></script></body></html>'''
for key,value in [('SPRITE',sprite),('NAV',navhtml),('CHARTDATA',chart),('STORES',storehtml),('QUEUE',qhtml),('SEGMENTS',segments),('MIX',mixhtml),('SALES',money(sales)),('TRADING',str(trading)),('ISSUES',str(issues)),('TX',str(tx)),('AVG',money(sales/tx)),('WEEK',money(sum(s[1] for s in series))),('CALENDAR',icon('calendar')),('SEARCH',icon('search')),('SETTINGS',icon('settings')),('BELL',icon('bell')),('CHART',icon('chart')),('LIST',icon('list')),('BOX',icon('box')),('ALERT',icon('alert')),('PLUS',icon('plus')),('COUNT',icon('count')),('SYNC',icon('sync')),('FILE',icon('file')),('ARROW',icon('arrow'))]:page=page.replace(key,value)
page=page.replace('../seven-taste/assets/motion/','assets/motion/')
page=page.replace('<img src="retailos-mark.svg" alt="">','<img src="retailos-mark.svg" width="37" height="37" alt="">')
page=page.replace('</style>', '''
.app{grid-template-columns:252px minmax(0,1fr)}.navitem span{white-space:nowrap}.nav-label{font-size:10px}.store-table td:first-child b{font-size:11px}.store-table small,.queue-row small,.queue-note,.footer{font-size:10px}.store-table th{font-size:10px}.metric-label,.heading p,.btn{font-size:12px}.scope-row>span,.kpi small,.panel-head p,.panel-head a,.plot-meta,.sales-caption,.mix-row{font-size:11px}.axis,.xaxis{font-size:10px}.mix-row small,.donut small{font-size:10px}
</style>''')
(out/'index.html').write_text(page,encoding='utf-8')
(out/'design-notes.md').write_text('Software — internal multi-store retail workspace.\nTaste: restrained neutral surfaces, cobalt brand accent, Manrope, consistent radius, real local aggregate data.\nDesktop concept only. Global navigation, POS scope, sales analytics, operational queue, ranked stores, source mix and quick actions.\nNo live application code or business data changed.\n',encoding='utf-8')
print(out/'index.html')
